use std::io

fn find(names: Vec<string>, n: string) -> i64 {
    let mut i = 0
    while i < names.len() {
        if names[i] == n {
            return i as i64
        }
        i += 1
    }
    return -1
}

fn main() {
    let mut names: Vec<string> = Vec::new()
    let mut bals: Vec<i64> = Vec::new()
    let input = std::io::read_all()
    for line in input.split("\n") {
        let p: Vec<string> = line.trim().split(" ").filter(|s| s.len() > 0).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0].clone()
        if cmd == "open" {
            let amt: i64 = p[2].parse().unwrap()
            if amt < 0 {
                println("error: invalid amount")
            } else if find(names.clone(), p[1].clone()) >= 0 {
                println("error: duplicate account")
            } else {
                names.push(p[1].clone())
                bals.push(amt)
                println("ok")
            }
        } else if cmd == "balance" {
            let i = find(names.clone(), p[1].clone())
            if i < 0 {
                println("error: unknown account {}", p[1])
            } else {
                println("{}", bals[i as usize])
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt: i64 = p[2].parse().unwrap()
            let i = find(names.clone(), p[1].clone())
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account {}", p[1])
            } else if cmd == "deposit" {
                bals[i as usize] = bals[i as usize] + amt
                println("ok")
            } else if bals[i as usize] < amt {
                println("error: insufficient funds")
            } else {
                bals[i as usize] = bals[i as usize] - amt
                println("ok")
            }
        } else if cmd == "transfer" {
            let amt: i64 = p[3].parse().unwrap()
            let i = find(names.clone(), p[1].clone())
            let j = find(names.clone(), p[2].clone())
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account {}", p[1])
            } else if j < 0 {
                println("error: unknown account {}", p[2])
            } else if i == j {
                println("error: same account")
            } else if bals[i as usize] < amt {
                println("error: insufficient funds")
            } else {
                bals[i as usize] = bals[i as usize] - amt
                bals[j as usize] = bals[j as usize] + amt
                println("ok")
            }
        }
    }
    let mut idx: Vec<usize> = Vec::new()
    let mut k = 0
    while k < names.len() {
        idx.push(k)
        k += 1
    }
    idx.sort_by(|a, b| names[*a].cmp(&names[*b]))
    for q in idx {
        println("{} {}", names[q], bals[q])
    }
}

